-- Zach Herbert, Texas House District 112.
-- Depends on tx_politician_district (tx_tracker.politicians.district).
-- Promises are verbatim lines from zach4texas.com and from @Zach4Texas.
-- New rows start pending. No status update is written until there is a public act.
-- List items under "What Zach will fight for" keep that heading with the item.

do $$
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'tx_tracker'
      and table_name = 'politicians'
      and column_name = 'district'
  ) then
    raise exception 'tx_tracker.politicians.district is missing. Apply tx_politician_district first.';
  end if;
end $$;

insert into tx_tracker.politicians (
  name, slug, office, district, party, election_date, term_start,
  x_handle, x_user_id, campaign_site_url, status,
  portrait_url, portrait_credit, portrait_source_url
) values (
  'Zach Herbert',
  'zach-herbert',
  'tx_house',
  '112',
  'Democratic',
  date '2026-11-03',
  date '2027-01-12',
  'Zach4Texas',
  '1961023791137779712',
  'https://zach4texas.com/',
  'elect',
  'https://zach4texas.com/wp-content/uploads/2025/09/Profile-Pic.jpg',
  'Photo: Zach Herbert for Texas campaign',
  'https://zach4texas.com/'
)
on conflict (slug) do update set
  name = excluded.name,
  office = excluded.office,
  district = excluded.district,
  party = excluded.party,
  election_date = excluded.election_date,
  term_start = excluded.term_start,
  x_handle = excluded.x_handle,
  x_user_id = excluded.x_user_id,
  campaign_site_url = excluded.campaign_site_url,
  status = excluded.status,
  portrait_url = excluded.portrait_url,
  portrait_credit = excluded.portrait_credit,
  portrait_source_url = excluded.portrait_source_url,
  updated_at = now();

with person as (
  select id from tx_tracker.politicians where slug = 'zach-herbert'
), incoming (source_type, url, title, published_at) as (
  values
    ($zh$campaign_page$zh$, $zh$https://zach4texas.com/issues/$zh$, $zh$Issues – Zach For Texas$zh$, null::timestamptz),
    ($zh$campaign_page$zh$, $zh$https://zach4texas.com/education/$zh$, $zh$Education – Zach For Texas$zh$, null::timestamptz),
    ($zh$campaign_page$zh$, $zh$https://zach4texas.com/healthcare-access/$zh$, $zh$healthcare-access – Zach For Texas$zh$, null::timestamptz),
    ($zh$campaign_page$zh$, $zh$https://zach4texas.com/economic-opportunity/$zh$, $zh$Economic-Opportunity – Zach For Texas$zh$, null::timestamptz),
    ($zh$campaign_page$zh$, $zh$https://zach4texas.com/workers-rights/$zh$, $zh$Workers-Rights – Zach For Texas$zh$, null::timestamptz),
    ($zh$campaign_page$zh$, $zh$https://zach4texas.com/faq/$zh$, $zh$FAQ – Zach For Texas$zh$, null::timestamptz),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/2107878988815450301$zh$, $zh$X post 2107878988815450301$zh$, timestamptz $zh$2026-10-07T17:01:28Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/2103957520087990513$zh$, $zh$X post 2103957520087990513$zh$, timestamptz $zh$2026-09-26T21:18:57Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/2099471192239350083$zh$, $zh$X post 2099471192239350083$zh$, timestamptz $zh$2026-09-14T12:11:53Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/2097679660222202026$zh$, $zh$X post 2097679660222202026$zh$, timestamptz $zh$2026-09-09T13:32:58Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/2095841367633047627$zh$, $zh$X post 2095841367633047627$zh$, timestamptz $zh$2026-09-04T11:48:15Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/1976244563850461308$zh$, $zh$X post 1976244563850461308$zh$, timestamptz $zh$2025-10-09T11:13:15Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/1963642815516201097$zh$, $zh$X post 1963642815516201097$zh$, timestamptz $zh$2025-09-04T16:38:24Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/2100956549149609998$zh$, $zh$X post 2100956549149609998$zh$, timestamptz $zh$2026-09-18T14:34:09Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/2101290772171477057$zh$, $zh$X post 2101290772171477057$zh$, timestamptz $zh$2026-09-19T12:42:14Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/2079998047203823711$zh$, $zh$X post 2079998047203823711$zh$, timestamptz $zh$2026-07-22T18:32:33Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/2093669787528262085$zh$, $zh$X post 2093669787528262085$zh$, timestamptz $zh$2026-08-29T11:59:10Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/2108254045487895034$zh$, $zh$X post 2108254045487895034$zh$, timestamptz $zh$2026-10-08T17:51:48Z$zh$),
    ($zh$x_post$zh$, $zh$https://x.com/Zach4Texas/status/2000603221438705881$zh$, $zh$X post 2000603221438705881$zh$, timestamptz $zh$2025-12-15T16:25:52Z$zh$)
), upserted as (
  insert into tx_tracker.sources (politician_id, source_type, url, title, published_at)
  select person.id, incoming.source_type, incoming.url, incoming.title, incoming.published_at
  from incoming
  cross join person
  on conflict (politician_id, url) do update set
    title = excluded.title,
    source_type = excluded.source_type,
    published_at = excluded.published_at
  returning id, url
), incoming_promises (summary_text, topic, date_said, source_url, verbatim_quote, promise_type, notes) as (
  values
    ($zh$I believe our Teachers are grossly underpaid and should be rewarded for their hard work. Good Teachers should be paid a good salary, and great Teachers should be rewarded in kind.$zh$, $zh$public_education$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe our Teachers are grossly underpaid and should be rewarded for their hard work. Good Teachers should be paid a good salary, and great Teachers should be rewarded in kind.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I believe in Pre-K for all Texans.$zh$, $zh$public_education$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe in Pre-K for all Texans.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I believe in increasing access to healthcare and expanding Medicaid, so that no Texan is left without lifesaving care merely because they cannot afford it.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe in increasing access to healthcare and expanding Medicaid, so that no Texan is left without lifesaving care merely because they cannot afford it.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I believe that the minimum wage should be increased to a livable wage, and that any Texan who works a full-time job should be able to make ends meet.$zh$, $zh$labor$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe that the minimum wage should be increased to a livable wage, and that any Texan who works a full-time job should be able to make ends meet.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I believe that women should have the unequivocal right to make medical decisions for their own bodies.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe that women should have the unequivocal right to make medical decisions for their own bodies.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I believe in protecting women’s access to the ballot box and oppose any legislation akin to the SAVE Act.$zh$, $zh$corruption_democracy$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe in protecting women’s access to the ballot box and oppose any legislation akin to the SAVE Act.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I believe in local Democracy, and the Texas Legislature should not preempt the decisions communities make for their respective jurisdictions.$zh$, $zh$local_control$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe in local Democracy, and the Texas Legislature should not preempt the decisions communities make for their respective jurisdictions.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I believe small businesses should be prioritized over large corporations.$zh$, $zh$labor_business$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe small businesses should be prioritized over large corporations.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I believe every small business should be able to afford to pay a living wage and full medical benefits for all Texas employees.$zh$, $zh$labor_business$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe every small business should be able to afford to pay a living wage and full medical benefits for all Texas employees.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I believe in the basic right to bear arms.$zh$, $zh$public_safety_justice$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe in the basic right to bear arms.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I believe that guns are inherently dangerous, and common-sense gun safety measures should be implemented to keep guns out of the hands of criminals and others deemed dangerous to themselves.$zh$, $zh$public_safety_justice$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe that guns are inherently dangerous, and common-sense gun safety measures should be implemented to keep guns out of the hands of criminals and others deemed dangerous to themselves.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I believe that diversity is what makes us Texans, and all Texans are equally deserving of dignity, respect, inclusion, and equitable treatment.$zh$, $zh$equity$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I believe that diversity is what makes us Texans, and all Texans are equally deserving of dignity, respect, inclusion, and equitable treatment.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$I will oppose any legislation that infringes on the rights of the few, and promote equity and ensure that Texans of all backgrounds are treated with dignity and respect.$zh$, $zh$equity$zh$, null::date, $zh$https://zach4texas.com/issues/$zh$, $zh$I will oppose any legislation that infringes on the rights of the few, and promote equity and ensure that Texans of all backgrounds are treated with dignity and respect.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$At the same time, the Legislature set aside up to $1 billion for vouchers that send public dollars to private schools with little accountability. Zach believes that’s the wrong priority.$zh$, $zh$public_education$zh$, null::date, $zh$https://zach4texas.com/education/$zh$, $zh$At the same time, the Legislature set aside up to $1 billion for vouchers that send public dollars to private schools with little accountability. Zach believes that’s the wrong priority.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$What Zach will fight for in Austin: Real funding for the basics. Raise core operating funding, keep it tied to actual costs, and fund schools based on enrollment instead of daily attendance.$zh$, $zh$public_education$zh$, null::date, $zh$https://zach4texas.com/education/$zh$, $zh$What Zach will fight for in Austin: Real funding for the basics. Raise core operating funding, keep it tied to actual costs, and fund schools based on enrollment instead of daily attendance.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$What Zach will fight for in Austin: Keep good teachers in the classroom. Competitive pay, real mentoring, paid residencies, and clear pathways to full certification.$zh$, $zh$public_education$zh$, null::date, $zh$https://zach4texas.com/education/$zh$, $zh$What Zach will fight for in Austin: Keep good teachers in the classroom. Competitive pay, real mentoring, paid residencies, and clear pathways to full certification.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$What Zach will fight for in Austin: Catch problems early. Spot reading and math gaps sooner, and fund the tutoring and small-group help that gets kids back on track.$zh$, $zh$public_education$zh$, null::date, $zh$https://zach4texas.com/education/$zh$, $zh$What Zach will fight for in Austin: Catch problems early. Spot reading and math gaps sooner, and fund the tutoring and small-group help that gets kids back on track.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$What Zach will fight for in Austin: Fully fund our highest-need students. Students with disabilities and other high-need kids deserve evaluations, specialized instruction, language services, and transportation, paid for in full.$zh$, $zh$public_education$zh$, null::date, $zh$https://zach4texas.com/education/$zh$, $zh$What Zach will fight for in Austin: Fully fund our highest-need students. Students with disabilities and other high-need kids deserve evaluations, specialized instruction, language services, and transportation, paid for in full.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$What Zach will fight for in Austin: Hold every dollar accountable. Any program that takes public money, including vouchers, should report every year on what it spends, who it serves, and how students actually do.$zh$, $zh$public_education$zh$, null::date, $zh$https://zach4texas.com/education/$zh$, $zh$What Zach will fight for in Austin: Hold every dollar accountable. Any program that takes public money, including vouchers, should report every year on what it spends, who it serves, and how students actually do.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$Public schools are where Zach’s kids, and most kids in this district, get their start. He’s running to make sure the state stops shortchanging them.$zh$, $zh$public_education$zh$, null::date, $zh$https://zach4texas.com/education/$zh$, $zh$Public schools are where Zach’s kids, and most kids in this district, get their start. He’s running to make sure the state stops shortchanging them.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$No Texan should go without care because they can't afford it.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/healthcare-access/$zh$, $zh$No Texan should go without care because they can't afford it.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$As your State Representative, Zach will fight to make sure every Texan — no matter their zip code or their paycheck — can get the care they need, when they need it.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/healthcare-access/$zh$, $zh$As your State Representative, Zach will fight to make sure every Texan — no matter their zip code or their paycheck — can get the care they need, when they need it.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Expand Medicaid. Texas remains one of the few states that has refused to expand Medicaid, leaving hundreds of thousands of working Texans caught in a coverage gap — they earn too much for traditional Medicaid but too little to afford private insurance. Zach supports closing that gap so no Texan is left without lifesaving care simply because they can’t afford it.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/healthcare-access/$zh$, $zh$Expand Medicaid. Texas remains one of the few states that has refused to expand Medicaid, leaving hundreds of thousands of working Texans caught in a coverage gap — they earn too much for traditional Medicaid but too little to afford private insurance. Zach supports closing that gap so no Texan is left without lifesaving care simply because they can’t afford it.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Lower the cost of care. Rising premiums, surprise bills, and out-of-pocket costs are squeezing families in District 112. Zach believes the Legislature should be working to bring costs down — not standing by while Texans get priced out of basic care.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/healthcare-access/$zh$, $zh$Lower the cost of care. Rising premiums, surprise bills, and out-of-pocket costs are squeezing families in District 112. Zach believes the Legislature should be working to bring costs down — not standing by while Texans get priced out of basic care.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Protect rural and community hospitals. When hospitals close or cut services, entire communities lose access to care — sometimes forcing families to drive hours for treatment. Zach supports policies that keep local hospitals and clinics open and fully staffed.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/healthcare-access/$zh$, $zh$Protect rural and community hospitals. When hospitals close or cut services, entire communities lose access to care — sometimes forcing families to drive hours for treatment. Zach supports policies that keep local hospitals and clinics open and fully staffed.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Support small businesses that want to cover their employees. As a small business owner himself, Zach knows how hard it is to offer good health coverage while keeping the doors open. He’ll push for options that make it more affordable for small businesses to provide real health benefits to their employees.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/healthcare-access/$zh$, $zh$Support small businesses that want to cover their employees. As a small business owner himself, Zach knows how hard it is to offer good health coverage while keeping the doors open. He’ll push for options that make it more affordable for small businesses to provide real health benefits to their employees.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Protect women’s access to healthcare decisions. Zach believes women should have the unequivocal right to make their own medical decisions, and he’ll oppose efforts in Austin to interfere with that right.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/healthcare-access/$zh$, $zh$Protect women’s access to healthcare decisions. Zach believes women should have the unequivocal right to make their own medical decisions, and he’ll oppose efforts in Austin to interfere with that right.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Cut the red tape between patients and care. Too many Texans spend more time fighting insurance denials and navigating bureaucracy than actually getting treated. Zach supports commonsense reforms that put patients — not paperwork — first.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/healthcare-access/$zh$, $zh$Cut the red tape between patients and care. Too many Texans spend more time fighting insurance denials and navigating bureaucracy than actually getting treated. Zach supports commonsense reforms that put patients — not paperwork — first.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Every Texan who works hard should be able to get ahead — not just get by.$zh$, $zh$affordability$zh$, null::date, $zh$https://zach4texas.com/economic-opportunity/$zh$, $zh$Every Texan who works hard should be able to get ahead — not just get by.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Zach is running to make sure the Texas Legislature is finally focused on the affordability crisis instead of ignoring it.$zh$, $zh$affordability$zh$, null::date, $zh$https://zach4texas.com/economic-opportunity/$zh$, $zh$Zach is running to make sure the Texas Legislature is finally focused on the affordability crisis instead of ignoring it.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Real property tax relief. Texans don’t need accounting tricks or one-time gimmicks — they need property tax relief that actually lowers what they owe, year after year. Zach will push for reforms that provide honest, lasting relief to homeowners in District 112.$zh$, $zh$taxes_cost_of_living$zh$, null::date, $zh$https://zach4texas.com/economic-opportunity/$zh$, $zh$Real property tax relief. Texans don’t need accounting tricks or one-time gimmicks — they need property tax relief that actually lowers what they owe, year after year. Zach will push for reforms that provide honest, lasting relief to homeowners in District 112.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$A livable minimum wage. No one who works full-time in Texas should be unable to make ends meet. Zach supports raising the minimum wage to a level that reflects the real cost of living, so hard work is enough to get by.$zh$, $zh$labor$zh$, null::date, $zh$https://zach4texas.com/economic-opportunity/$zh$, $zh$A livable minimum wage. No one who works full-time in Texas should be unable to make ends meet. Zach supports raising the minimum wage to a level that reflects the real cost of living, so hard work is enough to get by.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Prioritize small businesses over big corporations. Zach believes Texas’s economic policy has tilted too far toward large, out-of-state corporations at the expense of the small businesses that anchor local communities. He’ll fight to cut red tape and permitting delays that hold back local entrepreneurs, and support policies that make it easier — not harder — to start and grow a business here.$zh$, $zh$labor_business$zh$, null::date, $zh$https://zach4texas.com/economic-opportunity/$zh$, $zh$Prioritize small businesses over big corporations. Zach believes Texas’s economic policy has tilted too far toward large, out-of-state corporations at the expense of the small businesses that anchor local communities. He’ll fight to cut red tape and permitting delays that hold back local entrepreneurs, and support policies that make it easier — not harder — to start and grow a business here.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Affordable healthcare for workers and employers alike. As a small business owner, Zach knows firsthand how hard it is to offer real health coverage while staying afloat. He supports expanding affordable healthcare options so business owners can cover their employees without being priced out.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/economic-opportunity/$zh$, $zh$Affordable healthcare for workers and employers alike. As a small business owner, Zach knows firsthand how hard it is to offer real health coverage while staying afloat. He supports expanding affordable healthcare options so business owners can cover their employees without being priced out.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Invest in workforce training. Zach supports investing in workforce training through Texas community colleges, so workers can build the skills employers need and access higher-paying jobs without taking on unsustainable debt.$zh$, $zh$labor$zh$, null::date, $zh$https://zach4texas.com/economic-opportunity/$zh$, $zh$Invest in workforce training. Zach supports investing in workforce training through Texas community colleges, so workers can build the skills employers need and access higher-paying jobs without taking on unsustainable debt.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$A Legislature focused on Texans, not political fights. Zach believes Austin should be spending its time on the issues that actually affect people’s wallets and paychecks — not on partisan battles that do nothing for families in District 112.$zh$, $zh$affordability$zh$, null::date, $zh$https://zach4texas.com/economic-opportunity/$zh$, $zh$A Legislature focused on Texans, not political fights. Zach believes Austin should be spending its time on the issues that actually affect people’s wallets and paychecks — not on partisan battles that do nothing for families in District 112.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$If you show up and put in the work, you should be able to build a life on it.$zh$, $zh$labor$zh$, null::date, $zh$https://zach4texas.com/workers-rights/$zh$, $zh$If you show up and put in the work, you should be able to build a life on it.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$What Zach will fight for: Real credit for military experience. Veterans shouldn’t have to start from zero. Zach supports making it easier for military training, leadership experience, and technical certifications earned in the service to count toward civilian licensing and job qualifications.$zh$, $zh$veterans$zh$, null::date, $zh$https://zach4texas.com/workers-rights/$zh$, $zh$What Zach will fight for: Real credit for military experience. Veterans shouldn’t have to start from zero. Zach supports making it easier for military training, leadership experience, and technical certifications earned in the service to count toward civilian licensing and job qualifications.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$What Zach will fight for: Veteran hiring support. Zach backs incentives for Texas employers who prioritize hiring veterans and give them a real path to advancement, not just an entry-level job.$zh$, $zh$veterans$zh$, null::date, $zh$https://zach4texas.com/workers-rights/$zh$, $zh$What Zach will fight for: Veteran hiring support. Zach backs incentives for Texas employers who prioritize hiring veterans and give them a real path to advancement, not just an entry-level job.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$What Zach will fight for: A Legislature that shows up for veterans, not just on Veterans Day. Having worn the uniform himself, Zach believes veterans deserve a representative who treats their concerns as a year-round priority — not a photo opportunity.$zh$, $zh$veterans$zh$, null::date, $zh$https://zach4texas.com/workers-rights/$zh$, $zh$What Zach will fight for: A Legislature that shows up for veterans, not just on Veterans Day. Having worn the uniform himself, Zach believes veterans deserve a representative who treats their concerns as a year-round priority — not a photo opportunity.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$What Zach will fight for: A minimum wage you can actually live on. If you work full-time in Texas, you should be able to pay your bills. Zach supports raising the minimum wage to a real, livable level.$zh$, $zh$labor$zh$, null::date, $zh$https://zach4texas.com/workers-rights/$zh$, $zh$What Zach will fight for: A minimum wage you can actually live on. If you work full-time in Texas, you should be able to pay your bills. Zach supports raising the minimum wage to a real, livable level.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$What Zach will fight for: Employers who can afford to do right by their workers. Zach supports policies that help small and mid-size businesses afford to pay a living wage and offer full medical benefits — so doing right by employees isn’t just for big corporations that can absorb the cost.$zh$, $zh$labor_business$zh$, null::date, $zh$https://zach4texas.com/workers-rights/$zh$, $zh$What Zach will fight for: Employers who can afford to do right by their workers. Zach supports policies that help small and mid-size businesses afford to pay a living wage and offer full medical benefits — so doing right by employees isn’t just for big corporations that can absorb the cost.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$What Zach will fight for: Workforce training that leads somewhere. Zach supports investment in workforce training through Texas community colleges, so workers can build real skills and move into better-paying jobs without taking on crushing debt to get there.$zh$, $zh$labor$zh$, null::date, $zh$https://zach4texas.com/workers-rights/$zh$, $zh$What Zach will fight for: Workforce training that leads somewhere. Zach supports investment in workforce training through Texas community colleges, so workers can build real skills and move into better-paying jobs without taking on crushing debt to get there.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$What Zach will fight for: Protection on the job. Zach believes workers who get hurt or treated unfairly on the job deserve a fair shot — not a legal system stacked against them by powerful interests, which is exactly what he’s spent his career fighting in the courtroom.$zh$, $zh$labor$zh$, null::date, $zh$https://zach4texas.com/workers-rights/$zh$, $zh$What Zach will fight for: Protection on the job. Zach believes workers who get hurt or treated unfairly on the job deserve a fair shot — not a legal system stacked against them by powerful interests, which is exactly what he’s spent his career fighting in the courtroom.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$What Zach will fight for: An economy that puts local workers and local businesses first. Zach believes Texas policy has tilted too far toward big, out-of-state corporations. He’ll fight to prioritize the small businesses and the working people of District 112 instead.$zh$, $zh$labor_business$zh$, null::date, $zh$https://zach4texas.com/workers-rights/$zh$, $zh$What Zach will fight for: An economy that puts local workers and local businesses first. Zach believes Texas policy has tilted too far toward big, out-of-state corporations. He’ll fight to prioritize the small businesses and the working people of District 112 instead.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page. The section heading and the list item are stored together.$zh$),
    ($zh$Herbert’s top priorities are: fully funding neighborhood public schools and paying teachers competitively; providing property tax relief that meaningfully lowers bills; improving healthcare access and lowering costs; and refocusing the Legislature on issues that directly affect District 112 residents rather than partisan fights.$zh$, null::text, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$Herbert’s top priorities are: fully funding neighborhood public schools and paying teachers competitively; providing property tax relief that meaningfully lowers bills; improving healthcare access and lowering costs; and refocusing the Legislature on issues that directly affect District 112 residents rather than partisan fights.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Herbert says public school teachers are significantly underpaid and should be compensated well for their work, with strong teachers rewarded accordingly. He also supports universal pre-K access for all Texas children. He has called for the state’s basic per-student funding allotment to be raised, tied to enrollment, and indexed to inflation so districts don’t have to make staffing cuts, along with reduced pressure from high-stakes standardized testing.$zh$, $zh$public_education$zh$, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$Herbert says public school teachers are significantly underpaid and should be compensated well for their work, with strong teachers rewarded accordingly. He also supports universal pre-K access for all Texas children. He has called for the state’s basic per-student funding allotment to be raised, tied to enrollment, and indexed to inflation so districts don’t have to make staffing cuts, along with reduced pressure from high-stakes standardized testing.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Zach Herbert supports expanding access to healthcare and expanding Medicaid in Texas, arguing that no Texan should go without life-saving care simply because they can’t afford it.$zh$, $zh$health_care$zh$, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$Zach Herbert supports expanding access to healthcare and expanding Medicaid in Texas, arguing that no Texan should go without life-saving care simply because they can’t afford it.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Zach Herbert supports raising the minimum wage to a livable wage, expanding Medicaid access to lower healthcare costs for more families, raising teacher pay, and supporting small businesses so that they can afford to give employees both liveable wages and full medical benefits.$zh$, $zh$affordability$zh$, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$Zach Herbert supports raising the minimum wage to a livable wage, expanding Medicaid access to lower healthcare costs for more families, raising teacher pay, and supporting small businesses so that they can afford to give employees both liveable wages and full medical benefits.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Zach Herbert supports raising the minimum wage to a livable level, saying that anyone working a full-time job should be able to make ends meet.$zh$, $zh$labor$zh$, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$Zach Herbert supports raising the minimum wage to a livable level, saying that anyone working a full-time job should be able to make ends meet.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Zach Herbert supports women having full authority over their own medical decisions, including reproductive care. He also says he supports protecting women’s access to voting and opposes any legislation similar to the federal SAVE Act (a voter ID/citizenship-verification bill critics say could complicate voter registration for married women who have changed their names).$zh$, null::text, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$Zach Herbert supports women having full authority over their own medical decisions, including reproductive care. He also says he supports protecting women’s access to voting and opposes any legislation similar to the federal SAVE Act (a voter ID/citizenship-verification bill critics say could complicate voter registration for married women who have changed their names).$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Zach Herbert believes in local democratic authority, saying the Texas Legislature should not override or preempt decisions made by individual cities and communities within their own jurisdictions. He is committed to being the voice of his district in Austin so that its municipalities and school systems maintain jurisdiction over their own budget priorities and educational policies.$zh$, $zh$local_control$zh$, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$Zach Herbert believes in local democratic authority, saying the Texas Legislature should not override or preempt decisions made by individual cities and communities within their own jurisdictions. He is committed to being the voice of his district in Austin so that its municipalities and school systems maintain jurisdiction over their own budget priorities and educational policies.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$As a small business owner himself, Zach Herbert says small businesses should be prioritized over large corporations in state policy. He supports making it feasible for small businesses to pay employees a livable wage as well as full medical benefits. Herbert will push to cut red tape and permitting delays, expand affordable healthcare options for small-business owners to offer employees, and invest in workforce training through community colleges.$zh$, $zh$labor_business$zh$, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$As a small business owner himself, Zach Herbert says small businesses should be prioritized over large corporations in state policy. He supports making it feasible for small businesses to pay employees a livable wage as well as full medical benefits. Herbert will push to cut red tape and permitting delays, expand affordable healthcare options for small-business owners to offer employees, and invest in workforce training through community colleges.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Zach Herbert affirms the basic right to bear arms but supports common-sense gun safety measures aimed at keeping firearms away from criminals and people deemed a danger to themselves or others.$zh$, $zh$public_safety_justice$zh$, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$Zach Herbert affirms the basic right to bear arms but supports common-sense gun safety measures aimed at keeping firearms away from criminals and people deemed a danger to themselves or others.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Zach Herbert says diversity is core to Texas identity and that all Texans deserve dignity, respect, and equitable treatment regardless of background. He states he would oppose legislation that infringes on the rights of minority groups.$zh$, $zh$equity$zh$, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$Zach Herbert says diversity is core to Texas identity and that all Texans deserve dignity, respect, and equitable treatment regardless of background. He states he would oppose legislation that infringes on the rights of minority groups.$zh$, $zh$explicit_pledge$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Zach Herbert has called for property tax relief that actually lowers bills rather than relying on accounting or budget shifts that don’t provide real relief to homeowners.$zh$, $zh$taxes_cost_of_living$zh$, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$Zach Herbert has called for property tax relief that actually lowers bills rather than relying on accounting or budget shifts that don’t provide real relief to homeowners.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$Herbert’s goal is to make Texas more fair, which includes ensuring that Texans have access to quality education, healthcare, economic opportunity, and equal treatment.$zh$, null::text, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$Herbert’s goal is to make Texas more fair, which includes ensuring that Texans have access to quality education, healthcare, economic opportunity, and equal treatment.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
    ($zh$He frames his campaign around accountability, fully funded schools, and addressing what he calls an affordability crisis for families.$zh$, null::text, null::date, $zh$https://zach4texas.com/faq/$zh$, $zh$He frames his campaign around accountability, fully funded schools, and addressing what he calls an affordability crisis for families.$zh$, $zh$platform$zh$, $zh$Extracted verbatim from campaign_page$zh$),
