insert into tx_tracker.promises (
  politician_id, summary_text, topic, date_said, source_id, source_url,
  verbatim_quote, status, confidence, notes, promise_type
)
select
  person.id,
  p.summary_text,
  p.topic,
  p.date_said,
  upserted.id,
  p.source_url,
  p.verbatim_quote,
  'pending',
  'high',
  p.notes,
  p.promise_type
from incoming_promises p
cross join person
join upserted on upserted.url = p.source_url
on conflict (politician_id, source_url, verbatim_quote) do nothing;

